def actual_row_model():
    image=Image.new('RGB',(720,1280),(42,42,42))
    with Image.open(io.BytesIO(base64.b64decode(ROW_PIXELS_BASE64))) as strip:image.paste(strip,tuple(PIXEL_BOX[:2]))
    metadata=copy.deepcopy(ACTUAL_METADATA)
    rendered=io.BytesIO();image.save(rendered,format='PNG')
    metadata['screenshot_sha256']=hashlib.sha256(rendered.getvalue()).hexdigest()
    metadata['fixture_scope']='Exact actual027 caption pixels only; synthetic outside pixels, host-only model'
    return image,metadata


class SettingsRowTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.image,cls.original=actual_row_model()
        cls.updated=driver.settings_row_metadata(cls.image,copy.deepcopy(cls.original))
        cls.row=[word for word in cls.updated['words'] if word['bounds'][0]>=186 and 720<=(word['bounds'][1]+word['bounds'][3])/2<740]

    def light(self,metadata):return _light_options(_usable(metadata['words'],720,1280))[1]

    def test_actual_row_pixels_recover_exact_numeric_grammar_above75(self):
        self.assertIsNone(self.light(self.original))
        option=self.light(self.updated)
        self.assertEqual(option['variant'],'regular')
        self.assertEqual([word['text'] for word in option['suffix_words'][:2]],['(10073.62','MB)'])
        self.assertGreaterEqual(option['confidence'],75)
        transform=self.updated['settings_caption_ocr_transforms'][0]
        self.assertTrue(transform['same_current_caption_geometry'])
        self.assertEqual(transform['scale'],6)
        self.assertIn('10073.62',transform['tsv'])

    def mocked_row(self,mode):
        row=copy.deepcopy(self.row)
        number=next(word for word in row if word['text']=='(10073.62')
        if mode=='low':number['confidence']=74.999
        elif mode=='low-mb':next(word for word in row if word['text']=='MB)')['confidence']=74.999
        elif mode=='boundary':
            number['confidence']=75.
            next(word for word in row if word['text']=='MB)')['confidence']=75.
        elif mode=='unknown':number['text']='(1007:'
        elif mode=='auto-delete':number['text']='(Auto-delete'
        elif mode=='shift':next(word for word in row if word['text']=='Light')['bounds'][0]+=4
        elif mode=='ambiguous':row.append(copy.deepcopy(next(word for word in row if word['text']=='Light')))
        with patch.object(driver,'ocr_words',return_value=(row,{'tsv':'HOST_MODEL_NEGATIVE_ONLY'})):
            return driver.settings_row_metadata(self.image,copy.deepcopy(self.original))

    def test_low_malformed_and_auto_delete_only_do_not_become_regular(self):
        for mode in ('low','low-mb','unknown','auto-delete'):
            self.assertIsNone(self.light(self.mocked_row(mode)),mode)
        self.assertEqual(self.light(self.mocked_row('boundary'))['confidence'],75.)

    def test_shifted_or_ambiguous_caption_does_not_replace_original_words(self):
        for mode in ('shift','ambiguous'):
            updated=self.mocked_row(mode)
            self.assertEqual(updated['words'],self.original['words'])
            self.assertFalse(updated['settings_caption_ocr_transforms'][0]['same_current_caption_geometry'])

    def test_two_regular_rows_still_fail_shared_identity_grammar(self):
        updated=copy.deepcopy(self.updated)
        second=[]
        for word in self.row:
            clone=copy.deepcopy(word);clone['bounds'][1]+=35;clone['bounds'][3]+=35;second.append(clone)
        updated['words']+=second
        self.assertIsNone(self.light(updated))

    def test_helper_two_spatial_rows_preserves_ambiguity_and_auto_delete_distinction(self):
        for mode in ('regular','unknown','auto-delete'):
            metadata=copy.deepcopy(self.original)
            second=copy.deepcopy(self.row)
            for word in second:word['bounds'][1]+=35;word['bounds'][3]+=35
            metadata['words']+=copy.deepcopy(second)
            if mode=='unknown':next(word for word in second if word['text']=='(10073.62')['text']='(1007:'
            elif mode=='auto-delete':next(word for word in second if word['text']=='(10073.62')['text']='(Auto-delete'
            with patch.object(driver,'ocr_words',side_effect=[(copy.deepcopy(self.row),{'tsv':'HOST_MODEL_FIRST_ROW'}),
                (second,{'tsv':'HOST_MODEL_SECOND_ROW'})]) as read:
                updated=driver.settings_row_metadata(self.image,metadata)
            self.assertEqual(read.call_count,2)
            self.assertEqual(len(updated['settings_caption_ocr_transforms']),2)
            self.assertTrue(all(row['same_current_caption_geometry'] for row in updated['settings_caption_ocr_transforms']))
            if mode=='auto-delete':
                self.assertEqual(self.light(updated)['variant'],'regular')
                self.assertEqual([row['variant'] for row in _light_options(_usable(updated['words'],720,1280))[0]],['regular','auto-delete'])
            else:self.assertIsNone(self.light(updated),mode)

    def test_surface_low_prefix_and_duplicate_current_row_do_not_re_read(self):
        for mode in ('surface','low-prefix','duplicate-row'):
            metadata=copy.deepcopy(self.original)
            if mode=='surface':metadata['surface']['left']=1
            elif mode=='low-prefix':next(word for word in metadata['words'] if word['text']=='Light')['confidence']=74.999
            else:metadata['words'].append(copy.deepcopy(next(word for word in metadata['words'] if word['text']=='Light')))
            with patch.object(driver,'ocr_words') as read:
                self.assertEqual(driver.settings_row_metadata(self.image,metadata),metadata)
            read.assert_not_called()

    def test_original_valid_full_flow_never_calls_fallback_outside_blocked_settings(self):
        with patch.object(driver,'settings_row_metadata',side_effect=AssertionError('fallback outside exact blocked state')):
            baseline_flow.FullFlowBoundaryTests.test_full_path_continues_past_first_asset_response_and_120seconds_to_guarded_close_home(self)

    def test_extra_second_OCR_cost_keeps_original_eight_second_input_refusal(self):
        with tempfile.TemporaryDirectory() as temporary:
            evidence=Path(temporary);clock=SimpleNamespace(now=0.)
            clock.monotonic=lambda:clock.now;clock.sleep=lambda seconds:setattr(clock,'now',clock.now+seconds)
            image,metadata=synthetic_visible('full')
            original=copy.deepcopy(metadata)
            light=next(word for word in metadata['words'] if word['text']=='Light')
            y=(light['bounds'][1]+light['bounds'][3])/2
